#include <version>

// __cplusplus only reports the selected language mode. Compilers and standard
// libraries ship features on their own schedules and sometimes backport them
// into older modes, so gate on the feature, not on the edition.
#ifdef __cpp_lib_expected

#include <expected>

template<class T, class E>
using Result = std::expected<T, E>;

#else

#include <variant>

template<class T, class E>
class Result {
public:
    Result(T value) : storage_(value) {}
    Result(E error) : storage_(error) {}

    bool has_value() const { return storage_.index() == 0; }
    const T& operator*() const { return std::get<0>(storage_); }

private:
    std::variant<T, E> storage_;
};

#endif

int read_sequence() {
    Result<int, int> result{42};
    return *result;
}

#include <iostream>
#include <string>
#include <vector>

struct Order {
    std::string symbol;
    int quantity;
};

void print_orders(std::vector<Order>& orders) {
    for (const Order& order : orders) {
        std::cout << order.symbol << ' ';
    }

    // The same loop with the exposition-only variables spelled out: the range
    // expression is evaluated once and the endpoints obtained once.
    auto&& hidden_range = orders;
    auto hidden_begin = begin(hidden_range);
    auto hidden_end = end(hidden_range);
    for (; hidden_begin != hidden_end; ++hidden_begin) {
        const Order& order = *hidden_begin;
        std::cout << order.symbol << ' ';
    }

    // The range runs once; a by-value element copies once per iteration.
    for (auto order : orders) { static_cast<void>(order); }        // copies
    for (auto& order : orders) { order.quantity = 0; }             // mutates
    for (const auto& order : orders) { static_cast<void>(order); } // neither
}

#include <cstdint>
#include <iostream>
#include <map>
#include <string>
#include <tuple>

std::tuple<std::int64_t, int> best_bid() {
    return {10'025, 40};
}

void report(const std::map<std::string, int>& positions) {
    // The declaration before `[` initialises ONE hidden object; the names are
    // bindings into it. `auto` makes a copy, `auto&` binds the original.
    auto [bid_price, bid_quantity] = best_bid();
    std::cout << bid_price << ' ' << bid_quantity << '\n';

    // A by-value binding here would copy the whole pair - including the
    // std::string key - for every entry, even though only two names are read.
    for (const auto& [symbol, position] : positions) {
        std::cout << symbol << ": " << position << '\n';
    }
}

int main() {
    report({{"AAPL", 100}, {"MSFT", -50}});
}

#include <algorithm>
#include <compare>
#include <cstdint>
#include <string>

struct Price {
    std::int64_t ticks;

    // A DEFAULTED <=> also implicitly declares a defaulted ==.
    auto operator<=>(const Price&) const = default;
};

struct Symbol {
    std::string text;

    static char fold(char c) {
        return c >= 'A' && c <= 'Z' ? static_cast<char>(c - 'A' + 'a') : c;
    }

    // Weak, not strong: "AAPL" and "aapl" are equivalent but observably
    // different, so equal values are not substitutable.
    friend std::weak_ordering operator<=>(const Symbol& left,
                                          const Symbol& right) {
        return std::lexicographical_compare_three_way(
            left.text.begin(), left.text.end(),
            right.text.begin(), right.text.end(),
            [](char a, char b) { return fold(a) <=> fold(b); });
    }

    // A HAND-WRITTEN <=> supplies no ==, so it must be defined too.
    friend bool operator==(const Symbol& left, const Symbol& right) {
        return (left <=> right) == 0;
    }
};

bool checks() {
    return Price{1} < Price{2}
        && Symbol{"aapl"} == Symbol{"AAPL"};
}

#include <array>
#include <cstddef>
#include <cstdint>
#include <string_view>

// constexpr: PERMITTED in a constant expression, and required to run at
// compile time only where one is required. An ordinary call runs at runtime.
constexpr std::uint32_t crc_entry(std::uint32_t value) {
    for (int bit = 0; bit < 8; ++bit) {
        value = (value & 1U) ? 0xEDB88320U ^ (value >> 1)
                             : value >> 1;
    }
    return value;
}

constexpr auto make_crc_table() {
    std::array<std::uint32_t, 256> table{};
    for (std::size_t i = 0; i < table.size(); ++i) {
        table[i] = crc_entry(static_cast<std::uint32_t>(i));
    }
    return table;
}

inline constexpr auto crc_table = make_crc_table();
static_assert(crc_table[0] == 0);
static_assert(crc_table[1] == crc_entry(1));

// consteval: an immediate function. Every potentially evaluated call MUST be
// a constant expression, so a runtime call is a compile error by design.
consteval std::uint64_t hash_key(std::string_view key) {
    std::uint64_t hash = 1469598103934665603ULL;
    for (char c : key) {
        hash = (hash ^ static_cast<unsigned char>(c)) * 1099511628211ULL;
    }
    return hash;
}

constexpr auto order_key = hash_key("order");
static_assert(order_key != 0);

// constinit: constrains INITIALISATION only. No dynamic initialisation and no
// first-use guard - but the object stays mutable, unlike a constexpr variable.
constinit std::uint32_t messages_seen = 0;

std::uint32_t extend_crc(std::uint32_t crc, unsigned char byte) {
    ++messages_seen;
    return (crc >> 8) ^ crc_table[(crc ^ byte) & 0xFFU];
}

#include <cstdint>
#include <utility>

// Before: two members differing only in object qualification.
struct QuoteBefore {
    int price_;

    int& price() & { return price_; }
    const int& price() const & { return price_; }
};

// After: one member. Self is deduced exactly like a forwarding reference,
// so it becomes Quote&, const Quote& or Quote at the call site.
struct Quote {
    int price_;

    template<class Self>
    decltype(auto) price(this Self&& self) {
        // No implicit `this` here: every member must be reached through self.
        // Such a function also cannot be declared virtual.
        return std::forward<Self>(self).price_;
    }
};

struct Price {
    std::int64_t ticks;

    // By value: `self` is a copy, so the original is untouched. For a small
    // trivially copied type this can travel in registers.
    Price scaled(this Price self, std::int64_t factor) {
        self.ticks *= factor;
        return self;
    }
};

void use() {
    Quote quote{101};
    const Quote frozen{102};

    static_cast<void>(quote.price());
    static_cast<void>(frozen.price());
    static_cast<void>(Price{50}.scaled(2));
}
